from pathlib import Path
import pandas as pd, geopandas as gpd, matplotlib
matplotlib.use('Agg'); import matplotlib.pyplot as plt
from matplotlib import font_manager
root=Path('.'); fp=font_manager.FontProperties(fname=r'C:\Windows\Fonts\malgun.ttf'); s=pd.read_csv(root/'bus_supply/bus_data/processed/gtfs_stop_supply_2025.csv'); stopfile=list(root.glob('대중교통GTFS*2025*/*DataSet/stops.txt'))[0]; st=pd.read_csv(stopfile,dtype=str,usecols=['stop_id','stop_lat','stop_lon']); s=s.merge(st,on='stop_id',how='left'); w=s[s.day_type=='weekday'].copy(); pts=gpd.GeoDataFrame(w,geometry=gpd.points_from_xy(w.stop_lon.astype(float),w.stop_lat.astype(float)),crs=4326).to_crs(5179); poly=gpd.read_file('N3A_G0110000.shp',encoding='euc-kr').set_crs(5179,allow_override=True)[['BJCD','NAME','geometry']]; j=gpd.sjoin(pts,poly,predicate='within',how='inner'); a=j.groupby(['BJCD','NAME'],as_index=False).agg(departures=('departures','sum'),stops=('stop_id','nunique'),headway_min=('headway_min','mean'),geometry=('geometry','first')); a['per_10k']=a.departures/a.stops; a.to_csv(root/'visualizations/14_dong_supply/dong_supply.csv',index=False,encoding='utf-8-sig'); fig,ax=plt.subplots(figsize=(10,10)); gpd.GeoDataFrame(a,geometry='geometry',crs=5179).plot(column='per_10k',cmap='Blues',legend=True,ax=ax); ax.set_title('읍면동별 정류장당 평일 운행 공급량',fontproperties=fp,fontsize=18); ax.axis('off'); fig.savefig(root/'visualizations/14_dong_supply/dong_supply_map.png',dpi=180,bbox_inches='tight')
